Let $A$ and $B$ be the partite sets of $K_{a,b}$ with $|A|=a$ and $|B|=b$. Let $A_1\cup A_2=A$ and $B_1\cup B_2=B$ be partitions of $A$ and $B$ such that $|A_1|,|A_2|,|B_1|,|B_2|\geq k$. Let $\{a_{i,1},a_{i,2},\dots,a_{i,k}\}\subseteq A_i$ and $\{b_{i,1},b_{i,2},\dots,b_{i,k}\}\subseteq B_i$ be collections of $k$ distinct vertices for each $i\in [2]$.

		Let $c:E(K_{a, b}) \to [4]$ be defined as
		\[
		c(uv) = 
		\begin{cases}
			1, & \text{if } u \in A_1 \text{ and } v \in B_1. \\
			2, & \text{if } u \in A_1 \text{ and } v \in B_2. \\
			3, & \text{if } u \in A_2 \text{ and } v \in B_1. \\
			4, & \text{if } u \in A_2 \text{ and } v \in B_2. \\
		\end{cases}
		\]
		See Figure~\ref{figure K_{a,b} coloring} for a diagram of the coloring.

		\begin{figure}
			\begin{center}
				\begin{tikzpicture}[ultra thick,
					every node/.style={draw,circle},
					every fit/.style={ellipse,draw,inner sep=-2pt,text width=2cm}]



					\begin{scope}[xshift=.25cm,yshift=3cm,start chain=going below,node distance=3mm]
						\foreach \i in {1}
						\node[on chain] (a\i)  {$A_1$};
					\end{scope}


					\begin{scope}[xshift=.25cm,yshift=0cm,start chain=going below,node distance=3mm]
						\foreach \i in {2}
						\node[on chain] (a\i)  {$A_2$};
					\end{scope}


					\begin{scope}[xshift=3.75cm,yshift=3 cm,start chain=going below,node distance=3mm]
						\foreach \i in {1}
						\node[on chain] (b\i)  {$B_1$};
					\end{scope}

					\begin{scope}[xshift=3.75cm,yshift=0cm,start chain=going below,node distance=3mm]
						\foreach \i in {2}
						\node[on chain] (b\i)  {$B_2$};
					\end{scope}

					\draw [blue] (a1) -- (b1);
					\draw [red] (a1) -- (b2);
					\draw [green] (a2) -- (b1);
					\draw [orange] (a2) -- (b2);

				\end{tikzpicture}
				\caption{A rainbow $k$-connected coloring of $K_{a,b}$ when $a,b\geq 2k$.}\label{figure K_{a,b} coloring}
			\end{center}
		\end{figure}

		We will now show that the pair $(K_{a, b}, c)$ is rainbow $k$-connected. Consider two arbitrary vertices, $u, v \in V(K_{a,b})$. Without loss of generality, assume that $u \in A_1$.

		\textbf{Case 1:} $v\in A_1$. Then the collection $\{(u,b_{1,j},a_{2,j},b_{2,j},v)\mid j\in [k]\}$ is a collection of $k$ pairwise internally disjoint rainbow paths from $u$ to $v$.

		\textbf{Case 2:} $v\in A_2$. Then the collection $\{(u,b_{1,j},v)\mid j\in [k]\}$ gives us a collection of $k$ pairwise internally disjoint rainbow paths from $u$ to $v$.

		\textbf{Case 3:} $v\in B$. We will assume without loss of generality that $v\in B_1$. Then $\{(u,b_{2,j},a_{2,j},v)\mid j\in [k]\}$ is a collection of $k$ pairwise internally disjoint rainbow paths from $u$ to $v$.

		Thus, $(K_{a,b},c)$ is rainbow $k$-connected.

Let $s:=\left\lceil\frac{2k}{t-1}\right\rceil$ and let $K:=K_{a_1,a_2,\dots,a_t}$. Label the partite sets of $K$ and color the edges of $K$ according to $c:=c_{t,K}$, described in Construction~\ref{construction c_{t,K}}. For each $1\leq i\leq \frac{t-1}{2}$, let $\{a_{i,1},a_{i,2},\dots,a_{i,s}\}\subseteq A_i$ and  $\{b_{i,1},b_{i,2},\dots,b_{i,s}\}\subseteq B_i$ be collections of $s$ vertices. Let $s_1:=\left\lceil \frac{s}2\right\rceil$ and $s_2:=\left\lfloor \frac{s}2\right\rfloor$, and note that $s_1+s_2=s$.

		We want to show that there exist at least $k$ pairwise internally disjoint rainbow paths between any two vertices in $K$, Let $u,v\in V(K)$, and assume without loss of generality that $u\in A_1$.

		\textbf{Case 1:} $v\in A_1$. Then
		\[
		\{(u,a_{2,j},b_{2,j},v)\mid 1\leq j\leq s_1\}\cup \{(u,a_{2,s_1+j},b_{1,s_1+j},v)\mid 1\leq j\leq s_2\}\cup\{(u,b_{1,j},b_{2,s_1+j}, v)\mid 1\leq j\leq s_2\}
		\]
		give us a collection of pairwise internally disjoint rainbow paths from $u$ to $v$, all of which only use vertices in $A_2\cup B_1\cup B_2\cup \{u,v\}$, see Figure~\ref{fig::evenupperboundcase1} for an example of such paths when $s=2$ and $t=4$. We also will add the paths in
		\[
		\left\{(u,a_{i,j},b_{i,j},v)\mid 3\leq i\leq \frac{t}2,1\leq j\leq s\right\}.
		\]
		\begin{figure}[!ht]
			\begin{center}
				\begin{tikzpicture}[thick,
					every node/.style={draw,ellipse},
					every fit/.style={ellipse,draw,inner sep=-2pt}]


					\begin{scope}[xshift=1cm,yshift=0cm, start chain=going below,node distance=7mm]
						\foreach \i in {u, v}
						\node[transform shape, fill=black, circle, draw, scale = 0.5,on chain] (a\i) [label=above: $\i$] {};
					\end{scope}

					\begin{scope}[xshift=1cm,yshift=-4.5cm, start chain=going below,node distance=7mm]
						\foreach \i in {1, 2}
						\node[transform shape, fill=black, circle, draw, scale = 0.5,on chain] (a\i) [label=above: $a_{2,\i}$] {};
					\end{scope}

					\begin{scope}[xshift=6cm,yshift=0cm, start chain=going below,node distance=7mm]
						\foreach \i in {1, 2}
						\node[transform shape, fill=black, circle, draw, scale = 0.5,on chain] (b\i) [label=above: $b_{1,\i}$] {};
					\end{scope}

					\begin{scope}[xshift=6cm,yshift=-4.5cm, start chain=going below,node distance=7mm]
						\foreach \i in {1, 2}
						\node[transform shape, fill=black, circle, draw, scale = 0.5,on chain] (b2\i) [label=above: $b_{2,\i}$] {};
					\end{scope}

					\draw (1,-0.5) ellipse (.6cm and 1.45cm);

					\draw (6,-0.5) ellipse (.6cm and 1.45cm);

					\draw (1,-5) ellipse (.6cm and 1.45cm);

					\draw (6,-5) ellipse (.6cm and 1.45cm);

					\draw[red, ultra thick] (au) -- (b1);
					\draw[green, ultra thick] (a1) -- (b1);
					\draw [blue, ultra thick]   (av) to[out=-180,in=-180] (a1);

					\draw[red, ultra thick] (au) -- (b2);
					\draw[green, ultra thick] (av) -- (b21);
					\draw [blue, ultra thick]   (b2) to[out=0,in=0] (b21);

					\draw[green, ultra thick] (au) -- (b22);
					\draw[red, ultra thick] (a2) -- (b22);
					\draw [blue, ultra thick]   (av) to[out=-180,in=-180] (a2);

					\node[draw=none] at (-0,0.5) {$A_1$};
					\node[draw=none] at (-0,-6) {$A_2$};
					\node[draw=none] at (7,0.5) {$B_1$};
					\node[draw=none] at (7,-6) {$B_2$};


				\end{tikzpicture}
			\end{center}
			\caption{Three pairwise internally disjoint rainbow $u,v$-paths on a 4-partite graph $K$ colored according to $c_{4,K}$.}
			\label{fig::evenupperboundcase1}
		\end{figure}

		We claim that the total number of paths counted above is at least $k$. Indeed, if $s$ is even (so $s_1=s/2$), then the collection of paths contains every vertex in 
		\begin{equation}\label{expression set of vertices in paths}
			\left\{a_{i,j}\mid 2\leq i\leq t/2,1\leq j\leq s\right\}\cup \{b_{i,j}\mid 1\leq i\leq t/2,1\leq j\leq s\}
		\end{equation}
		as an internal vertex, and if $s$ is odd, then the collection of paths contains every vertex in~\eqref{expression set of vertices in paths} except $b_{1,s_1}$, so in all cases we have at least $(t-1)s-1$ vertices internal to the paths, and each path is of length $3$, so it contains exactly two internal vertices, so the number of paths is at least
		\[
		\frac{(t-1)s-1}2=\frac{t-1}2\left\lceil\frac{2k}{t-1}\right\rceil-\frac{1}2\geq k-\frac{1}{2}.
		\]
		Now, since the number of paths and $k$ are both integers, the above inequality implies that there are at least $k$ paths.

		\textbf{Case 2:} $v\in A\setminus A_1$, assume without loss of generality that $v\in A_2$. Then
		\[
		\left\{(u,a_{i,j},b_{i,j},v)\mid 3\leq i\leq \frac{t}2, 1\leq j\leq s\right\}\cup\{(u,b_{i,j},v)\mid 1\leq i\leq 2, 1\leq j\leq s\}
		\]
		contains $\frac{t}2s\geq \frac{t}2\cdot \frac{2k}{t-1}>k$ pairwise internally disjoint rainbow $u,v$-paths.

		\textbf{Case 3:} $v\in B$. Let $i^*\in [t/2]$ be such that $v\not\in B_{i^*}$. There is such $i^*$ since $t \ge 4$. Then
		\[
		\{(u,a_{i,j},v)\mid 2\leq i\leq \frac{t}2,1\leq j\leq s\}\cup \{(u,b_{i^*,j},v)\mid 1\leq j\leq s\}
		\]
		contains $\frac{t}2s\geq k$ pairwise internally disjoint rainbow paths from $u$ to $v$.

		Thus, $(K,c)$ is rainbow $k$-connected, and so $\mathrm{rc}_k(K)\leq 3$.

Let $A=\{a_1,a_2\}$, $B=\{b_1,b_2,b_3,b_4\}$ and $C=\{c_1,c_2,\dots,c_8,c_1',c_2',\dots,c_8'\}$ be the partite sets of $K:=K_{2,4,16}$. Let $\mathcal{B}=\{\mathbf{b}_1,\mathbf{b}_2,\dots,\mathbf{b}_8\}$ denote the collection of bit strings of length $4$ with an odd number of $0$'s, and let $b_{i,j}$ denote the value of the $j$th bit of $\mathbf{b}_i$.  We now define a coloring $c:E(K)\to \{0,1\}$. Let
		\[
		c(uv)=\begin{cases}
			0 &\text{ if }uv=a_ib_j\text{ for some }i\in [2],j\in[4]\\
			0 &\text{ if }uv=a_1c_j\text{ or }uv=a_2c_j'\text{ for }j\in [8],\\
			1 &\text{ if }uv=a_1c_j'\text{ or }uv=a_2c_j\text{ for }j\in [8],\\
			b_{i,j} & \text{ if }uv=b_jc_i\text{ or }uv=b_jc_i'\text{ for }i\in [8], j\in [4].
		\end{cases}
		\]

		We claim that $(K,c)$ is rainbow $2$-connected. Indeed, consider an arbitrary pair of vertices $x,y\in V(K)$.

	\begin{figure}[!b]
		\begin{center}
			\begin{tikzpicture}[thick,
				every node/.style={draw,ellipse},
				every fit/.style={ellipse,draw,inner sep=-2pt}]

				\begin{scope}[yshift = 2 cm]
					\begin{scope}[xshift = -2.25 cm]
						\foreach \i in {1,2,3,4,5,6,7,8}
						\node[transform shape, fill=black, circle, draw, scale = 0.5] (c\i) at (0.35*\i, 0) {};
						\node[dashed, fit= (c1) (c2) (c3) (c4) (c5) (c6) (c7) (c8), inner sep = 1 mm, label = above: \Large $C_L$] (allC1) {};
					\end{scope}
					\begin{scope} [xshift = 2.25 cm]
						\foreach \i in {1,2,3,4,5,6,7,8}
						\node[transform shape, fill=black, circle, draw, scale = 0.5] (d\i) at (0.35*\i, 0) {};
						\node[dashed, fit= (d1) (d2) (d3) (d4) (d5) (d6) (d7) (d8), inner sep = 1 mm, label = above: \Large $C_R$] (allD) {};
					\end{scope}
					\node[fit= (allC1) (allD), inner sep = 1 mm, label = above: \huge $C$] (allC) {};
				\end{scope}



				\begin{scope} [xshift = 5 cm, yshift = -5 cm]
					\foreach \i in {1,2,3,4}
					\node[fill=black, circle, draw, scale = 0.5, label = right: $b_{\i}$] (b\i) at (0, \i) {};
					\node[fit= (b1) (b2) (b3) (b4), inner sep = 1 mm, label=right: \huge $B$] (allB) {};
				\end{scope}

				\begin{scope} [xshift = -2 cm, yshift = -4 cm]
					\foreach \i in {1,2}
					\node[fill=black, circle, draw, scale = 0.5, label = left: $a_{\i}$] (a\i) at (0,\i) {};
					\node[ fit= (a1) (a2), inner sep = 1 mm, label = left: \huge $A$] (allA) {};
				\end{scope}


				\draw [blue, ultra thick] (a1) to (b1);
				\draw [blue, ultra thick] (a1) to (b2);
				\draw [blue, ultra thick] (a1) to (b3);
				\draw [blue, ultra thick] (a1) to (b4);

				\draw [blue, ultra thick] (a2) to (b1);
				\draw [blue, ultra thick] (a2) to (b2);
				\draw [blue, ultra thick] (a2) to (b3);
				\draw [blue, ultra thick] (a2) to (b4);

				\draw [red, ultra thick] (a2) to (allC1);
				\draw [red, ultra thick] (a1) to (allD);
				\draw [blue, ultra thick] (a1) to (allC1);
				\draw [blue, ultra thick] (a2) to (allD);
				\draw  (allC1)[black, ultra thick] -- node[draw = white, fill = white, inner sep = 0 mm] {$b_{i,j}$} (allB) ;
				\draw  (allD)[black, ultra thick] -- node[draw = white, fill = white, inner sep = 0 mm] {$b_{i,j}$} (allB) ;
			\end{tikzpicture}
		\end{center}
		\caption{The coloring of $K_{2,4,16}$ used in the proof of Theorem~\ref{thm: 2-4-16}. Here $C_L$ and $C_R$ represent the sets $\{c_1, \ldots, c_8\}$ and $\{c_1', \ldots, c_8'\}$, respectively.}
		\label{fig::2-4-16}
	\end{figure}	

		\textbf{Case 1:} $\{x,y\}=\{a_1,a_2\}$. Then $(x,c_1,y)$ and $(x,c_2,y)$ are pairwise internally disjoint rainbow paths.

		\textbf{Case 2:} $x\in A$ and $y\in B\cup C$ or $x\in B\cup C$ and $y\in A$, assume without loss of generality that $x\in A$, say $x=a_1$. First assume $y\in C$, say $y=c_i$. Note that for each $i\in [8]$, there exists a $j\in [4]$ such that $c_ib_j$ is color $1$, so $(x,y)$ and $(x,b_j,y)$ are pairwise internally disjoint rainbow paths. Now, if $y\in B$, say $y=b_i$, then note that for every $i\in [4]$ there exists a $j\in [8]$ such that $b_ic_j$ is color $1$. Hence, $(x,y)$ and $(x,c_j,y)$ are pairwise internally disjoint rainbow paths.

		\textbf{Case 3:} $x\in B$ and $y\in C$ or $x\in C$ and $y\in B$, assume $x\in B$. Then $(x,y)$ along with either $(x,a_1,y)$ or $(x,a_2,y)$ are pairwise internally disjoint rainbow paths.

		\textbf{Case 4:} $\{x,y\}\subseteq B$. Assume by symmetry that $x=b_1$ and $y=b_2$. Let $\mathbf{b}_i=0111$. Then $(x,c_i,y)$ and $(x,c_i',y)$ are pairwise internally disjoint rainbow paths.

		\textbf{Case 5:} $x=c_i$ and $y=c_j'$ or $x=c_i'$ and $y=c_j$ for some $i,j\in[8]$ (possibly with $i=j)$. Then $(x,a_1,y)$ and $(x,a_2,y)$ are pairwise internally disjoint rainbow paths.

		\textbf{Case 6:} $x=c_i$ and $y=c_j$ or $x=c_i'$ and $y=c_j'$ for some $i,j\in [8]$, assume $x=c_i$ and $y=c_j$. Note that $\mathbf{b}_i$ and $\mathbf{b}_j$ differ in at least two bits by construction, say $b_{i,s}\neq b_{j,s}$ and $b_{i,s'}\neq b_{j,s'}$ for some $s,s'\in [4]$. Then $(x,b_s,y)$ and $(x,b_{s'},y)$ are pairwise internally disjoint rainbow paths.

		Thus, in all cases, $x$ and $y$ are connected by two pairwise internally disjoint rainbow paths.
